#include <iostream>
#include <cstdio>
using namespace std;

int main() {
    float t1, v, t2;
    cin >> t1 >> v >> t2;
    float tt = 1000.0 / v + t2;
    if (tt < t1)
        printf("rabbit\n");
    else if (tt > t1)
        printf("turtle\n");
    else
        printf("tie\n");
    printf("%.2f\n", tt);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

int n;
long long f, ans;

int main() {
    scanf("%d", &n);
    f = 1;
    for (int i = 1; i <= n; i++) {
        ans += f;
        f *= 2;
    }
    printf("%lld\n", ans);
    return 0;
}
